end $function$

CREATE OR REPLACE FUNCTION private.reconcile_request_folder_completion_v2(p_request_folder text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  folder_value text := trim(coalesce(p_request_folder, ''));
  request_ids text[];
  membership_signature_value text;
  state_row private.ph_request_folder_delivery_state;
  all_complete boolean := false;
  dependency_keys text[];
  creation_dependency_coverage boolean := false;
  event_key_value text;
  completion_event public.ph_request_delivery_outbox;
begin
  if folder_value = '' then return jsonb_build_object('queued', false, 'reason', 'folder_missing'); end if;
  perform pg_advisory_xact_lock(hashtextextended('request-folder-v2:' || folder_value, 0));

  select coalesce(array_agg(r.unique_id order by r.unique_id), '{}'::text[]),
         coalesce(bool_and(lower(trim(coalesce(r.req_status, ''))) in ('complete','completed','done')
           or nullif(trim(coalesce(r.date_completed, '')), '') is not null), false)
    into request_ids, all_complete
  from public.ph_active_request r
  where trim(coalesce(r.request_folder, '')) = folder_value
    and coalesce(r.req_archived, false) = false
    and lower(trim(coalesce(r.req_status, 'pending'))) not in ('archived','cancelled','canceled');

  membership_signature_value := md5(coalesce(array_to_string(request_ids, E'\n'), 'empty'));
  select * into state_row from private.ph_request_folder_delivery_state
  where request_folder = folder_value for update;

  if state_row.request_folder is null then
    insert into private.ph_request_folder_delivery_state(
      request_folder, membership_version, membership_signature, active_request_ids)
    values (folder_value, 1, membership_signature_value, request_ids)
    returning * into state_row;
  elsif state_row.membership_signature <> membership_signature_value then
    update private.ph_request_folder_delivery_state set
      membership_version = membership_version + 1,
      membership_signature = membership_signature_value,
      active_request_ids = request_ids,
      completion_event_key = null,
      updated_at = now()
    where request_folder = folder_value returning * into state_row;
  else
    update private.ph_request_folder_delivery_state set active_request_ids = request_ids, updated_at = now()
    where request_folder = folder_value returning * into state_row;
  end if;

  update public.ph_request_delivery_outbox o set status = 'suppressed',
    sanitized_error_code = 'FOLDER_MEMBERSHIP_SUPERSEDED', updated_at = now()
  where o.request_folder = folder_value and o.event_type = 'request_completed'
    and o.status in ('pending','failed','unknown')
    and coalesce(o.payload->>'contractVersion', '') = 'request-folder-completion-v2'
    and coalesce((o.payload->>'membershipVersion')::bigint, 0) <> state_row.membership_version;

  if cardinality(request_ids) = 0 or not all_complete then
    return jsonb_build_object('queued', false, 'membershipVersion', state_row.membership_version,
      'activeCount', cardinality(request_ids), 'reason', 'folder_incomplete');
  end if;

  select coalesce(array_agg(o.event_key order by o.created_at, o.event_key), '{}'::text[])
    into dependency_keys
  from public.ph_request_delivery_outbox o
  where o.request_folder = folder_value
    and o.event_type in ('request_created', 'request_options_appended')
    and coalesce(o.payload->'request_ids', '[]'::jsonb) ?| request_ids;

  select coalesce(bool_and(exists (
    select 1 from public.ph_request_delivery_outbox membership
    where membership.request_folder = folder_value
      and membership.event_type in ('request_created', 'request_options_appended')
      and coalesce(membership.payload->'request_ids', '[]'::jsonb) ? active_request.request_id
  )), false) into creation_dependency_coverage
  from unnest(request_ids) as active_request(request_id);

  if not creation_dependency_coverage then
    return jsonb_build_object('queued', false, 'membershipVersion', state_row.membership_version,
      'activeCount', cardinality(request_ids), 'reason', 'waiting_for_request_membership_event');
  end if;

  event_key_value := 'request-folder-completed:' || md5(folder_value) || ':v' || state_row.membership_version::text;
  insert into public.ph_request_delivery_outbox(
    event_key, event_type, request_folder, payload, status, next_attempt_at)
  values (
    event_key_value, 'request_completed', folder_value,
    jsonb_build_object(
      'contractVersion', 'request-folder-completion-v2',
      'activeRequestIds', to_jsonb(request_ids), 'request_ids', to_jsonb(request_ids),
      'membershipVersion', state_row.membership_version,
      'membershipSignature', state_row.membership_signature,
      'dependencyEventKeys', to_jsonb(dependency_keys),
      'updatedCompletion', state_row.last_delivered_version > 0
    ), 'pending', now()
  ) on conflict (event_key) do update set
      payload = excluded.payload,
      status = case when public.ph_request_delivery_outbox.status = 'suppressed' then 'pending' else public.ph_request_delivery_outbox.status end,
      next_attempt_at = least(public.ph_request_delivery_outbox.next_attempt_at, now()),
      updated_at = now()
  returning * into completion_event;

  update private.ph_request_folder_delivery_state set completion_event_key = event_key_value, updated_at = now()
  where request_folder = folder_value;

  return jsonb_build_object('queued', true, 'eventId', completion_event.event_id,
    'membershipVersion', state_row.membership_version, 'activeCount', cardinality(request_ids));
end
$function$

CREATE OR REPLACE FUNCTION private.reconcile_request_folder_from_request_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE'
    and current_setting('app.request_archive_transition', true) = 'on' then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if row(
      old.unique_id, btrim(coalesce(old.request_folder,'')),
      not coalesce(old.req_archived,false)
        and lower(btrim(coalesce(old.req_status,'pending'))) not in ('archived','cancelled','canceled'),
      lower(btrim(coalesce(old.req_status,''))) in ('complete','completed','done')
        or nullif(btrim(coalesce(old.date_completed,'')),'') is not null
    ) is not distinct from row(
      new.unique_id, btrim(coalesce(new.request_folder,'')),
      not coalesce(new.req_archived,false)
        and lower(btrim(coalesce(new.req_status,'pending'))) not in ('archived','cancelled','canceled'),
      lower(btrim(coalesce(new.req_status,''))) in ('complete','completed','done')
        or nullif(btrim(coalesce(new.date_completed,'')),'') is not null
    ) then
      return new;
    end if;
  end if;
  if tg_op = 'DELETE' then
    perform private.reconcile_request_folder_completion_v2(old.request_folder);
    return old;
  end if;
  if tg_op = 'UPDATE' and old.request_folder is distinct from new.request_folder then
    perform private.reconcile_request_folder_completion_v2(old.request_folder);
  end if;
  perform private.reconcile_request_folder_completion_v2(new.request_folder);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.record_request_health_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  missing_history integer;
  missing_drive integer;
  exhausted_delivery integer;
  stalled_delivery integer;
  expired_leases integer;
  missing_threads integer;
  worker_stale integer;
  canary_stale integer;
  unassigned integer;
  active_codes integer;
  oldest_pending_seconds bigint;
  health_code text;
  health_severity text;
begin
  select count(*) into missing_history
  from public.ph_active_request r
  where (lower(coalesce(r.req_status, '')) in ('complete', 'completed')
         or nullif(btrim(coalesce(r.date_completed, '')), '') is not null)
    and not exists (select 1 from public.ph_request_history h where h.unique_id = r.unique_id);

  select count(*) into missing_drive
  from public.ph_active_request r
  where coalesce(r.req_archived, false) = false
    and lower(coalesce(r.req_status, 'pending')) not in ('complete', 'completed')
    and not exists (select 1 from public.ph_master_inventory m where m.unique_id = r.master_id);

  select count(*) into exhausted_delivery
  from public.ph_request_delivery_outbox where status = 'failed' and attempt_count >= 8;
  select count(*), coalesce(max(extract(epoch from (now() - created_at)))::bigint, 0)
    into stalled_delivery, oldest_pending_seconds
  from public.ph_request_delivery_outbox
  where status = 'pending' and next_attempt_at <= now() - interval '2 minutes';
  select count(*) into expired_leases
  from public.ph_request_delivery_outbox
  where status = 'processing' and coalesce(lease_expires_at, last_attempt_at) <= now();
  select count(*) into missing_threads
  from public.ph_request_delivery_outbox o
  where o.event_type = 'request_created' and o.status = 'delivered'
    and o.created_at >= now() - interval '24 hours'
    and not exists (
      select 1 from public.ph_request_email_threads t
      where t.request_folder = o.request_folder
        and nullif(btrim(coalesce(t.initial_thread_id, '')), '') is not null
    );
  select case when exists (
    select 1 from public.ph_request_delivery_worker_state
    where last_heartbeat_at >= now() - interval '3 minutes'
  ) then 0 else 1 end into worker_stale;
  select case when exists (
    select 1 from public.ph_request_delivery_outbox
    where event_type = 'delivery_canary' and status = 'delivered'
      and delivered_at >= now() - interval '10 minutes'
  ) then 0 else 1 end into canary_stale;
  select count(*) into unassigned from public.ph_warehouse_assigned_items
    where present_in_drive and nullif(btrim(coalesce(assignedto, '')), '') is null;
  select count(*) into active_codes from public.ph_warehouse_assigned_items where present_in_drive;

  health_code := case
    when stalled_delivery > 0 or worker_stale > 0 or canary_stale > 0 then 'DELIVERY_WORKER_STALLED'
    when expired_leases > 0 then 'DELIVERY_LEASE_EXPIRED'
    when exhausted_delivery > 0 then 'DELIVERY_RETRY_EXHAUSTED'
    when missing_threads > 0 then 'DELIVERY_THREAD_MISSING'
    when missing_history > 0 then 'MISSING_HISTORY'
    when missing_drive > 0 then 'DRIVE_ROW_MISSING'
    when unassigned > 0 then 'EVAL_ASSIGNMENT_GAP'
    else 'HEALTHY' end;
  health_severity := case
    when stalled_delivery > 0 or worker_stale > 0 or canary_stale > 0
      or expired_leases > 0 or exhausted_delivery > 0 or missing_history > 0 then 'error'
    when missing_threads > 0 or missing_drive > 0 or unassigned > 0 then 'warning'
    else 'info' end;

  insert into public.ph_app_health_events (
    event_name, area, severity, sanitized_code, sample_rate, metadata
  ) values (
    'scheduled_request_health_audit', 'request_integrity', health_severity,
    health_code, 1,
    jsonb_build_object(
      'missing_history_count', missing_history,
      'missing_drive_row_count', missing_drive,
      'delivery_retry_exhausted_count', exhausted_delivery,
      'delivery_stalled_count', stalled_delivery,
      'delivery_expired_lease_count', expired_leases,
      'delivery_missing_thread_count', missing_threads,
      'delivery_worker_stale_count', worker_stale,
      'delivery_canary_stale_count', canary_stale,
      'oldest_pending_seconds', oldest_pending_seconds,
      'unassigned_itemcode_count', unassigned,
      'drive_itemcode_count', active_codes
    )
  );

  return jsonb_build_object(
    'health_code', health_code,
    'missing_history_count', missing_history,
    'missing_drive_row_count', missing_drive,
    'delivery_retry_exhausted_count', exhausted_delivery,
    'delivery_stalled_count', stalled_delivery,
    'delivery_expired_lease_count', expired_leases,
    'delivery_missing_thread_count', missing_threads,
    'delivery_worker_stale_count', worker_stale,
    'delivery_canary_stale_count', canary_stale,
    'oldest_pending_seconds', oldest_pending_seconds,
    'unassigned_itemcode_count', unassigned,
    'drive_itemcode_count', active_codes
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_eligible_season_sales_itemcode_v1(p_itemcode text, p_import_revision text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  settings jsonb := private.season_sales_settings_v1();
  current_season text := upper(btrim(coalesce(settings->>'seasonCode', '')));
  current_sales_year integer := private.season_sales_year_v1(settings->>'salesYear');
  normalized_itemcode text := upper(btrim(coalesce(p_itemcode, '')));
  item_scope_exists boolean := false;
  classified_count integer := 0;
  reconcile_result jsonb;
begin
  perform set_config('lock_timeout', '1500', true);
  perform set_config('statement_timeout', '12000', true);

  if normalized_itemcode = '' then
    return jsonb_build_object('ok', true, 'status', 'skipped',
      'code', 'SEASON_SALES_ITEMCODE_REQUIRED');
  end if;
  if current_season = '' or current_sales_year is null then
    return jsonb_build_object('ok', true, 'status', 'maintenance_deferred',
      'code', 'SEASON_SALES_SETTINGS_INVALID');
  end if;

  -- Serialize only this ITEMCODE.  A concurrent caller will perform the same
  -- deterministic classification, so a busy result is safe and retryable.
  if not pg_try_advisory_xact_lock(
    hashtextextended('season-sales-itemcode-v1:' || normalized_itemcode, 0)
  ) then
    return jsonb_build_object('ok', true, 'status', 'maintenance_deferred',
      'code', 'MAINTENANCE_DEFERRED');
  end if;

  select exists (
    select 1
    from public.ph_master_inventory candidate
    where upper(btrim(coalesce(candidate.itemcode, ''))) = normalized_itemcode
      and upper(btrim(coalesce(candidate.season, ''))) = current_season
      and private.season_sales_year_v1(candidate.saleyear) <= current_sales_year
      and upper(btrim(coalesce(candidate.end_cap_folder, ''))) in ('', 'NULL', 'N/A', '-')
      and not private.season_sales_assignment_protected_v1(candidate.app_tab_assignment)
      and (
        lower(btrim(coalesce(candidate.app_tab_assignment, ''))) in ('season', 'location')
        or coalesce(private.season_sales_safe_numeric_v1(candidate.s_lts), 0) > 0
        or exists (
          select 1
          from public.ph_season_sales_office_state state
          where state.season_code = current_season
            and state.sales_year = current_sales_year
            and state.itemcode_normalized = normalized_itemcode
        )
      )
  ) into item_scope_exists;

  if not item_scope_exists then
    return jsonb_build_object('ok', true, 'status', 'skipped',
      'code', 'NOT_SEASON_SALES_SCOPE');
  end if;

  with ranked as (
    select candidate.unique_id,
      row_number() over (
        order by coalesce(private.season_sales_safe_numeric_v1(candidate.ptravailable), -1) desc,
          btrim(candidate.priority)::integer asc,
          private.eval_work_natural_sort_key_v1(candidate.locationcode),
          private.eval_work_natural_sort_key_v1(candidate.lotcode),
          candidate.unique_id
      ) as winner_rank
    from public.ph_master_inventory candidate
    where upper(btrim(coalesce(candidate.itemcode, ''))) = normalized_itemcode
      and upper(btrim(coalesce(candidate.season, ''))) = current_season
      and private.season_sales_year_v1(candidate.saleyear) <= current_sales_year
      and btrim(coalesce(candidate.priority, '')) ~ '^[1-4]$'
      and upper(btrim(coalesce(candidate.end_cap_folder, ''))) in ('', 'NULL', 'N/A', '-')
      and upper(coalesce(candidate.holdstopcode, '')) !~ '[HS]'
      and not private.season_sales_assignment_protected_v1(candidate.app_tab_assignment)
  ), winner as (
    select ranked.unique_id
    from ranked
    where ranked.winner_rank = 1
  )
  update public.ph_master_inventory target
  set app_tab_assignment = case
        when target.unique_id = (select winner.unique_id from winner) then 'season'
        else 'location'
      end,
      last_updated = coalesce(target.last_updated, now())
  where upper(btrim(coalesce(target.itemcode, ''))) = normalized_itemcode
    and upper(btrim(coalesce(target.season, ''))) = current_season
    and private.season_sales_year_v1(target.saleyear) <= current_sales_year
    and upper(btrim(coalesce(target.end_cap_folder, ''))) in ('', 'NULL', 'N/A', '-')
    and not private.season_sales_assignment_protected_v1(target.app_tab_assignment)
    and target.app_tab_assignment is distinct from case
      when target.unique_id = (select winner.unique_id from winner) then 'season'
      else 'location'
    end;
  get diagnostics classified_count = row_count;

  reconcile_result := public.reconcile_season_sales_office_v1(
    array[normalized_itemcode],
    false,
    left(coalesce(nullif(btrim(p_import_revision), ''), 'scoped-refresh'), 180),
    p_idempotency_key
  );

  return coalesce(reconcile_result, '{}'::jsonb)
    || jsonb_build_object('classifiedCount', classified_count);
exception
  when lock_not_available or query_canceled then
    return jsonb_build_object('ok', true, 'status', 'maintenance_deferred',
      'code', 'MAINTENANCE_DEFERRED');
end
$function$

CREATE OR REPLACE FUNCTION private.require_active_flyer_creator_profile()
 RETURNS public.profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_profile public.profiles%rowtype;
  v_username text;
  v_role text;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'AUTHENTICATION_REQUIRED';
  end if;

  select * into v_profile
  from public.profiles
  where id = auth.uid();

  v_username := lower(btrim(coalesce(v_profile.username, '')));
  v_role := upper(btrim(coalesce(v_profile.role, '')));

  if not found
     or v_profile.disabled_at is not null
     or (v_profile.locked_until is not null and v_profile.locked_until > now())
     or not (
       v_role in ('ADMIN', 'ADMINISTRATOR')
       or v_username in ('dylan_collyge', 'megan_kelly')
     ) then
    raise exception using errcode = '42501', message = 'ACTIVE_FLYER_CREATOR_REQUIRED';
  end if;

  return v_profile;
end
$function$

CREATE OR REPLACE FUNCTION private.require_codex_ops_dylan_v1()
 RETURNS public.profiles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile public.profiles%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'CODEX_OPS_AUTH_REQUIRED';
  end if;
  select p.* into profile
  from public.profiles p
  where p.id = auth.uid()
    and lower(btrim(p.username)) = 'dylan_collyge'
    and p.disabled_at is null
    and (p.locked_until is null or p.locked_until <= now());
  if profile.id is null then
    raise exception using errcode = '42501', message = 'CODEX_OPS_DYLAN_ONLY';
  end if;
  return profile;
end;
$function$

CREATE OR REPLACE FUNCTION private.route_legacy_request_completion_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.event_type = 'request_completed'
     and coalesce(new.payload->>'contractVersion', '') <> 'request-folder-completion-v2' then
    perform private.reconcile_request_folder_completion_v2(new.request_folder);
    new.status := 'suppressed';
    new.sanitized_error_code := 'FOLDER_COMPLETION_V2_SUPERSEDED';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.save_drive_evidence_core_v2(p_master_uid text, p_expected_itemcode text, p_expected_locationcode text, p_expected_lotcode text, p_expected_signature text, p_baseline jsonb, p_evidence jsonb, p_complete boolean, p_workflow text, p_idempotency_key text, p_allow_field_merge boolean, p_contract_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor public.profiles%rowtype;
  v_row public.ph_master_inventory%rowtype;
  v_saved public.ph_master_inventory%rowtype;
  v_existing private.drive_evidence_idempotency%rowtype;
  v_payload jsonb := coalesce(p_evidence, '{}'::jsonb);
  v_baseline jsonb := coalesce(p_baseline, '{}'::jsonb);
  v_current_fields jsonb;
  v_request_hash text;
  v_response jsonb;
  v_request_rows jsonb := '[]'::jsonb;
  v_unexpected_keys text[];
  v_conflict_fields text[] := '{}'::text[];
  v_workflow text := lower(btrim(coalesce(p_workflow, '')));
  v_saved_at timestamptz := clock_timestamp();
  v_expected_signature timestamptz;
  v_is_stale boolean := false;
begin
  v_actor := private.require_active_admin_profile();

  if char_length(btrim(coalesce(p_idempotency_key, ''))) not between 12 and 180 then
    raise exception using errcode = '22023', message = 'INVALID_IDEMPOTENCY_KEY';
  end if;
  if char_length(btrim(coalesce(p_master_uid, ''))) not between 1 and 240 then
    raise exception using errcode = '22023', message = 'INVALID_MASTER_IDENTITY';
  end if;
  if v_workflow not in ('season', 'location', 'notes') then
    raise exception using errcode = '22023', message = 'INVALID_DRIVE_WORKFLOW';
  end if;
  if jsonb_typeof(v_payload) <> 'object'
     or (coalesce(p_allow_field_merge, false) and jsonb_typeof(v_baseline) <> 'object') then
    raise exception using errcode = '22023', message = 'INVALID_EVIDENCE_PAYLOAD';
  end if;

  select array_agg(key order by key) into v_unexpected_keys
  from jsonb_object_keys(v_payload) as keys(key)
  where key not in ('spec', 'caliper', 'match', 'loc_match_qty', 'initial_ptr',
    'av_note', 'pick_note', 'comments', 'photo_link', 'photo_name');
  if coalesce(cardinality(v_unexpected_keys), 0) > 0 then
    raise exception using errcode = '22023', message = 'UNSUPPORTED_DRIVE_EVIDENCE_FIELD';
  end if;
  if octet_length(v_payload::text) > 65536 or octet_length(v_baseline::text) > 65536 then
    raise exception using errcode = '22023', message = 'DRIVE_EVIDENCE_PAYLOAD_TOO_LARGE';
  end if;
  if v_payload ? 'match'
     and nullif(btrim(v_payload ->> 'match'), '') is not null
     and (v_payload ->> 'match') !~ '^([0-9]{1,2}([.][0-9]+)?|100([.]0+)?)$' then
    raise exception using errcode = '22023', message = 'INVALID_LOC_MATCH_PERCENT';
  end if;
  if v_payload ? 'photo_link' and octet_length(coalesce(v_payload ->> 'photo_link', '')) > 16000 then
    raise exception using errcode = '22023', message = 'PHOTO_REFERENCE_TOO_LARGE';
  end if;

  begin
    v_expected_signature := nullif(btrim(coalesce(p_expected_signature, '')), '')::timestamptz;
  exception when invalid_datetime_format or datetime_field_overflow then
    raise exception using errcode = '22023', message = 'INVALID_EXPECTED_SIGNATURE';
  end;

  v_request_hash := md5(concat_ws('|',
    btrim(p_master_uid),
    btrim(coalesce(p_expected_itemcode, '')),
    btrim(coalesce(p_expected_locationcode, '')),
    btrim(coalesce(p_expected_lotcode, '')),
    btrim(coalesce(p_expected_signature, '')),
    v_baseline::text,
    v_payload::text,
    coalesce(p_complete, false)::text,
    v_workflow,
    coalesce(p_allow_field_merge, false)::text,
    coalesce(p_contract_version, '')
  ));

  select * into v_existing
  from private.drive_evidence_idempotency
  where profile_id = v_actor.id
    and idempotency_key = btrim(p_idempotency_key);
  if found then
    if v_existing.request_hash <> v_request_hash then
      return jsonb_build_object(
        'ok', false,
        'code', 'IDEMPOTENCY_CONFLICT',
        'canonicalConfirmed', false,
        'retryBlocked', true,
        'recovered', false
      );
    end if;
    return jsonb_set(v_existing.response_payload, '{recovered}', 'true'::jsonb, true);
  end if;

  -- The idempotency and row locks are deliberately non-blocking. A busy result
  -- is transient and is never persisted, allowing the same token one bounded retry.
  if not pg_try_advisory_xact_lock(hashtextextended(
    'drive-evidence-idempotency:' || v_actor.id::text || ':' || btrim(p_idempotency_key), 0
  )) then
    return jsonb_build_object(
      'ok', false,
      'code', 'DRIVE_SAVE_BUSY',
      'canonicalConfirmed', false,
      'retryAfterMs', 250,
      'retryBlocked', false,
      'recovered', false
    );
  end if;

  select * into v_existing
  from private.drive_evidence_idempotency
  where profile_id = v_actor.id
    and idempotency_key = btrim(p_idempotency_key);
  if found then
    if v_existing.request_hash <> v_request_hash then
      return jsonb_build_object(
        'ok', false,
        'code', 'IDEMPOTENCY_CONFLICT',
        'canonicalConfirmed', false,
        'retryBlocked', true,
        'recovered', false
      );
    end if;
    return jsonb_set(v_existing.response_payload, '{recovered}', 'true'::jsonb, true);
  end if;

  if not pg_try_advisory_xact_lock(hashtextextended('drive-evidence-row:' || btrim(p_master_uid), 0)) then
    return jsonb_build_object(
      'ok', false,
      'code', 'DRIVE_SAVE_BUSY',
      'canonicalConfirmed', false,
      'retryAfterMs', 300,
      'retryBlocked', false,
      'recovered', false
    );
  end if;

  select * into v_row
  from public.ph_master_inventory
  where unique_id = btrim(p_master_uid);

  if not found then
    v_response := jsonb_build_object(
      'ok', false,
      'code', 'DRIVE_ROW_NOT_FOUND',
      'canonicalConfirmed', true,
      'retryBlocked', true,
      'recovered', false
    );
    return private.store_drive_evidence_terminal_v2(
      v_actor.id, p_idempotency_key, v_request_hash, v_response,
      'DRIVE_ROW_NOT_FOUND', now() + interval '24 hours'
    );
  end if;

  if upper(btrim(coalesce(v_row.itemcode, ''))) <> upper(btrim(coalesce(p_expected_itemcode, '')))
     or upper(btrim(coalesce(v_row.locationcode, ''))) <> upper(btrim(coalesce(p_expected_locationcode, '')))
     or upper(btrim(coalesce(v_row.lotcode, ''))) <> upper(btrim(coalesce(p_expected_lotcode, ''))) then
    v_response := jsonb_build_object(
      'ok', false,
      'code', 'DRIVE_ROW_IDENTITY_CONFLICT',
      'canonicalConfirmed', true,
      'row', to_jsonb(v_row),
      'retryBlocked', true,
      'recovered', false
    );
    return private.store_drive_evidence_terminal_v2(
      v_actor.id, p_idempotency_key, v_request_hash, v_response,
      'DRIVE_ROW_IDENTITY_CONFLICT', now() + interval '24 hours'
    );
  end if;

  v_current_fields := jsonb_build_object(
    'spec', v_row.spec,
    'caliper', v_row.caliper,
    'match', v_row.match,
    'loc_match_qty', v_row.loc_match_qty,
    'initial_ptr', v_row.initial_ptr,
    'av_note', v_row.av_note,
    'pick_note', v_row.pic_note,
    'comments', v_row.sales_note,
    'photo_link', v_row.photo_link,
    'photo_name', v_row.photo_name
  );
  v_is_stale := v_expected_signature is not null
    and v_row.last_updated is distinct from v_expected_signature;

  if v_is_stale and (not coalesce(p_allow_field_merge, false) or coalesce(p_complete, false)) then
    v_response := jsonb_build_object(
      'ok', false,
      'code', case when coalesce(p_complete, false) then 'DRIVE_COMPLETION_STALE' else 'DRIVE_ROW_STALE' end,
      'canonicalConfirmed', true,
      'row', to_jsonb(v_row),
      'conflictFields', '[]'::jsonb,
      'retryBlocked', true,
      'recovered', false
    );
    return private.store_drive_evidence_terminal_v2(
      v_actor.id, p_idempotency_key, v_request_hash, v_response,
      case when coalesce(p_complete, false) then 'DRIVE_COMPLETION_STALE' else 'DRIVE_ROW_STALE' end,
      now() + interval '24 hours'
    );
  end if;

  if v_is_stale and coalesce(p_allow_field_merge, false) then
    select coalesce(array_agg(key order by key), '{}'::text[])
      into v_conflict_fields
    from jsonb_object_keys(v_payload) as keys(key)
    where not (v_baseline ? key)
       or coalesce(v_baseline ->> key, '') is distinct from coalesce(v_current_fields ->> key, '');

    if cardinality(v_conflict_fields) > 0 then
      v_response := jsonb_build_object(
        'ok', false,
        'code', 'DRIVE_FIELD_CONFLICT',
        'canonicalConfirmed', true,
        'row', to_jsonb(v_row),
        'conflictFields', to_jsonb(v_conflict_fields),
        'retryBlocked', true,
        'recovered', false
      );
      return private.store_drive_evidence_terminal_v2(
        v_actor.id, p_idempotency_key, v_request_hash, v_response,
        'DRIVE_FIELD_CONFLICT', now() + interval '24 hours'
      );
    end if;
  end if;

  update public.ph_master_inventory
  set spec = case when v_payload ? 'spec' then nullif(btrim(v_payload ->> 'spec'), '') else spec end,
      caliper = case when v_payload ? 'caliper' then nullif(btrim(v_payload ->> 'caliper'), '') else caliper end,
      match = case when v_payload ? 'match' then nullif(btrim(v_payload ->> 'match'), '') else match end,
      loc_match_qty = case when v_payload ? 'loc_match_qty' then nullif(btrim(v_payload ->> 'loc_match_qty'), '') else loc_match_qty end,
      initial_ptr = case when v_payload ? 'initial_ptr' then nullif(btrim(v_payload ->> 'initial_ptr'), '') else initial_ptr end,
      av_note = case when v_payload ? 'av_note' then nullif(btrim(v_payload ->> 'av_note'), '') else av_note end,
      pic_note = case when v_payload ? 'pick_note' then nullif(btrim(v_payload ->> 'pick_note'), '') else pic_note end,
      sales_note = case when v_payload ? 'comments' then nullif(v_payload ->> 'comments', '') else sales_note end,
      photo_link = case when v_payload ? 'photo_link' then nullif(btrim(v_payload ->> 'photo_link'), '') else photo_link end,
      photo_name = case when v_payload ? 'photo_name' then nullif(btrim(v_payload ->> 'photo_name'), '') else photo_name end,
      date_completed = case when coalesce(p_complete, false) then v_saved_at else date_completed end,
      app_tab_assignment = case when coalesce(p_complete, false) then v_workflow else app_tab_assignment end,
      av_rule_priority_snapshot = case when v_payload <> '{}'::jsonb then priority else av_rule_priority_snapshot end,
      av_rule_holdstop_snapshot = case when v_payload <> '{}'::jsonb then concat_ws('|',
        nullif(btrim(coalesce(holdstopcode, '')), ''),
        nullif(btrim(coalesce(holdstopreason, '')), '')
      ) else av_rule_holdstop_snapshot end,
      av_rule_spec_updated_at = case when v_payload ? 'spec' then v_saved_at else av_rule_spec_updated_at end,
      av_rule_caliper_updated_at = case when v_payload ? 'caliper' then v_saved_at else av_rule_caliper_updated_at end,
      av_rule_match_updated_at = case when v_payload ? 'match' then v_saved_at else av_rule_match_updated_at end,
      av_rule_av_note_updated_at = case when v_payload ? 'av_note' then v_saved_at else av_rule_av_note_updated_at end,
      av_rule_photo_updated_at = case when v_payload ? 'photo_link' or v_payload ? 'photo_name' then v_saved_at else av_rule_photo_updated_at end,
      av_rule_bundle_updated_at = case when v_payload <> '{}'::jsonb then v_saved_at else av_rule_bundle_updated_at end,
      last_updated = v_saved_at
  where unique_id = v_row.unique_id
    and last_updated is not distinct from v_row.last_updated
  returning * into v_saved;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'DRIVE_SAVE_BUSY',
      'canonicalConfirmed', false,
      'retryAfterMs', 350,
      'retryBlocked', false,
      'recovered', false
    );
  end if;

  with updated_requests as (
    update public.ph_active_request request
    set req_spec = v_saved.spec,
        req_caliper = v_saved.caliper,
        req_match = private.eval_work_safe_numeric_v1(v_saved.match),
        req_pic_note = v_saved.pic_note,
        req_sales_note = v_saved.sales_note,
        req_comments = v_saved.sales_note,
        av_note = v_saved.av_note,
        req_photo_link = v_saved.photo_link,
        req_photo_name = v_saved.photo_name,
        req_status = case when coalesce(p_complete, false) then 'Complete' else request.req_status end,
        date_completed = case when coalesce(p_complete, false) then v_saved_at::text else request.date_completed end,
        completed_by_username = case when coalesce(p_complete, false) then lower(btrim(v_actor.username)) else request.completed_by_username end,
        completed_by_display = case when coalesce(p_complete, false) then coalesce(nullif(btrim(v_actor.display_name), ''), v_actor.username) else request.completed_by_display end,
        app_tab_assignment = v_saved.app_tab_assignment,
        master_app_tab_assignment = v_saved.app_tab_assignment,
        row_version = coalesce(request.row_version, 0) + 1,
        updated_at = v_saved_at
    where request.master_id = v_row.unique_id
      and upper(btrim(coalesce(request.itemcode, ''))) = upper(btrim(coalesce(v_row.itemcode, '')))
      and upper(btrim(coalesce(request.locationcode, ''))) = upper(btrim(coalesce(v_row.locationcode, '')))
      and upper(btrim(coalesce(request.lotcode, ''))) = upper(btrim(coalesce(v_row.lotcode, '')))
      and coalesce(request.req_archived, false) = false
      and lower(btrim(coalesce(request.req_status, 'pending'))) not in ('complete','completed','done','archived','cancelled','canceled')
    returning request.*
  )
  select coalesce(jsonb_agg(to_jsonb(updated_requests) order by updated_requests.unique_id), '[]'::jsonb)
    into v_request_rows
  from updated_requests;

  v_response := jsonb_build_object(
    'ok', true,
    'code', 'SAVED',
    'contractVersion', coalesce(nullif(btrim(p_contract_version), ''), 'save-drive-evidence-v2'),
    'row', to_jsonb(v_saved),
    'requestRows', v_request_rows,
    'completed', coalesce(p_complete, false),
    'canonicalConfirmed', true,
    'mergedUnrelatedChanges', v_is_stale,
    'retryBlocked', false,
    'recovered', false
  );

  return private.store_drive_evidence_terminal_v2(
    v_actor.id, p_idempotency_key, v_request_hash, v_response, 'SAVED', null
  );
end
$function$

CREATE OR REPLACE FUNCTION private.season_sales_assert_actor_v1(p_username text)
 RETURNS public.profiles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.profiles;
  allowed boolean := false;
  allowed_usernames text[];
begin
  select profile.* into actor
  from public.profiles profile
  where lower(btrim(profile.username)) = lower(btrim(coalesce(p_username, '')))
    and profile.disabled_at is null
    and (profile.locked_until is null or profile.locked_until <= now())
    and not profile.must_change_password
  limit 1;
  if actor.id is null then
    raise exception using errcode = '42501', message = 'SEASON_SALES_PROFILE_NOT_ACTIVE';
  end if;

  select coalesce(permission.allowed, false) into allowed
  from private.get_effective_app_permissions_v1(
    actor.id, private.resolve_app_access_policy_id_v1(false)
  ) permission
  where permission.permission_key = 'module.sales-office.view'
  limit 1;
  if not coalesce(allowed, false) then
    raise exception using errcode = '42501', message = 'SEASON_SALES_PERMISSION_REQUIRED';
  end if;

  allowed_usernames := private.season_sales_note_allowed_usernames_v1();
  if not (lower(btrim(actor.username)) = any(allowed_usernames)) then
    raise exception using errcode = '42501', message = 'SEASON_SALES_USER_NOT_ASSIGNED';
  end if;
  return actor;
end
$function$

