CREATE OR REPLACE FUNCTION private.season_sales_evidence_v1(p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
declare
  photo_evidence jsonb := private.av_current_photo_evidence_v1(p_row);
  photo_at timestamptz := (photo_evidence->>'photoUpdatedAt')::timestamptz;
  reasons text[] := '{}'::text[];
  match_qty numeric := private.av_verified_photo_match_qty_v1(p_row);
  match_value numeric := private.av_evidence_number_v1(p_row->>'match');
  spec_value text := lower(btrim(coalesce(p_row->>'spec', '')));
  clear_text text := nullif(btrim(p_row->>'av_rule_last_cleared_at'), '');
  cleared_at timestamptz;
  ready boolean;
begin
  select coalesce(array_agg(value), '{}'::text[]) into reasons
  from jsonb_array_elements_text(photo_evidence->'reasons');
  if btrim(coalesce(p_row->>'av_note', '')) = '' then reasons := array_append(reasons, 'av_note_missing'); end if;
  if nullif(btrim(p_row->>'match'), '') is null then reasons := array_append(reasons, 'match_missing');
  elsif match_value is null or match_value < 0 or match_value > 100 then reasons := array_append(reasons, 'match_invalid'); end if;
  if spec_value !~ '[[:alnum:]]'
     or spec_value in ('n/a', 'na', 'n.a.', 'none', 'null', 'unknown', 'tbd') then
    reasons := array_append(reasons, 'spec_missing');
  end if;
  if match_qty is null or match_qty <= 0 then reasons := array_append(reasons, 'loc_match_qty_missing'); end if;
  cleared_at := private.av_evidence_timestamp_v1(clear_text);
  if clear_text is not null and cleared_at is null then reasons := array_append(reasons, 'evidence_timestamp_invalid');
  elsif cleared_at is not null and (photo_at is null or cleared_at >= photo_at) then
    reasons := array_append(reasons, coalesce(nullif(p_row->>'av_rule_last_clear_reason', ''), 'evidence_invalidated'));
  end if;
  ready := cardinality(reasons) = 0;
  return jsonb_build_object(
    'ready', ready,
    'status', case when ready then 'ready_for_custom_av' else 'needs_photo_data' end,
    'reasons', to_jsonb(reasons),
    -- Keep the existing response property for callers, but now it identifies
    -- the qualifying photo instead of an unrelated note edit.
    'bundleUpdatedAt', photo_at,
    'photoUpdatedAt', photo_at,
    'verifiedPhotoMatchQty', match_qty,
    -- Keep the existing fingerprint inputs byte-for-byte. No lifecycle or
    -- idempotency key changes; existing reconciliation handles invalid evidence.
    'fingerprint', encode(extensions.digest(concat_ws('|',
      coalesce(p_row->>'photo_link', ''), coalesce(p_row->>'photo_name', ''),
      coalesce(p_row->>'av_note', ''), coalesce(p_row->>'spec', ''),
      coalesce(p_row->>'caliper', ''), coalesce(p_row->>'match', ''),
      coalesce(p_row->>'loc_match_qty', ''), coalesce(p_row->>'av_rule_last_cleared_at', '')
    ), 'sha256'), 'hex')
  );
exception when others then
  return jsonb_build_object('ready', false, 'status', 'needs_photo_data',
    'reasons', jsonb_build_array('evidence_timestamp_invalid'), 'fingerprint', 'invalid');
end
$function$

CREATE OR REPLACE FUNCTION private.set_eval_report_settings_internal(p_low_stock_max_slts numeric, p_hold_age_days integer, p_location_note_age_days integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  settings public.ph_eval_report_settings%rowtype;
  manager_username text;
begin
  if not private.can_manage_eval_assignments() then
    raise exception using errcode = '42501', message = 'EVAL_REPORT_SETTINGS_FORBIDDEN';
  end if;
  if p_low_stock_max_slts is null
     or p_low_stock_max_slts < 0
     or p_low_stock_max_slts > 100000000 then
    raise exception using errcode = '22023', message = 'EVAL_REPORT_LOW_STOCK_LIMIT_INVALID';
  end if;
  if p_hold_age_days is null or p_hold_age_days < 0 or p_hold_age_days > 3650 then
    raise exception using errcode = '22023', message = 'EVAL_REPORT_HOLD_AGE_INVALID';
  end if;
  if p_location_note_age_days is null
     or p_location_note_age_days < 0
     or p_location_note_age_days > 3650 then
    raise exception using errcode = '22023', message = 'EVAL_REPORT_LOCATION_NOTE_AGE_INVALID';
  end if;

  manager_username := (private.current_active_profile()).username;

  insert into public.ph_eval_report_settings (
    singleton,
    low_stock_max_slts,
    hold_age_days,
    location_note_age_days,
    updated_by,
    updated_at
  ) values (
    true,
    p_low_stock_max_slts,
    p_hold_age_days,
    p_location_note_age_days,
    manager_username,
    now()
  )
  on conflict (singleton) do update set
    low_stock_max_slts = excluded.low_stock_max_slts,
    hold_age_days = excluded.hold_age_days,
    location_note_age_days = excluded.location_note_age_days,
    updated_by = excluded.updated_by,
    updated_at = excluded.updated_at
  returning * into settings;

  return jsonb_build_object(
    'low_stock_max_slts', settings.low_stock_max_slts,
    'hold_age_days', settings.hold_age_days,
    'location_note_age_days', settings.location_note_age_days,
    'updated_by', settings.updated_by,
    'updated_at', settings.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.stamp_request_batch_creator(p_requests jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile public.profiles%rowtype;
  stamped jsonb;
begin
  profile := private.current_active_profile();
  if profile.id is null then
    raise exception using errcode = '42501', message = 'REQUEST_PROFILE_REQUIRED';
  end if;
  if jsonb_typeof(p_requests) <> 'array' then
    return p_requests;
  end if;

  select coalesce(
    jsonb_agg(
      item.value || jsonb_build_object('request_created_by_username', profile.username)
      order by item.ordinality
    ),
    '[]'::jsonb
  )
  into stamped
  from jsonb_array_elements(p_requests) with ordinality as item(value, ordinality);

  return stamped;
end;
$function$

